        if(!$this->ok($a)||'imperium.oracle-model-comparative-assessment/v1'!==($a['schema']??null)||'ORACLE_COMPARATIVE_ASSESSMENT_SEALED_PENDING_AUGUR_RECOMMENDATION'!==($a['status']??null)||$authorityId!==($authority['authority_id']??null)||true!==($authority['recommendation_authority']??null)||true!==($authority['authority_single_use']??null)||$models!==($authority['candidate_models']??null)||($a['matrix_digest']??null)!==($authority['matrix_digest']??null)||($a['runtime_bindings']??null)!==($case['candidate_runtime_bindings']??null)
            ||!$this->ok($case)||($a['case']['digest']??null)!==($case['record_digest']??null)||!$this->ok($o)||$augurBindingId!==($o['binding_id']??null)||($case['instance_id']??null)!==($o['instance_id']??null)||($a['actor']['binding_id']??null)!==$augurBindingId||'ORACLE_AUGUR_BOUND_ACTIVE_NO_MODEL_SELECTION_AUTHORITY'!==($o['status']??null)
            ||!in_array($disposition,['RECOMMEND_MODEL','NO_UNIQUE_RECOMMENDATION','RECOMMEND_NONE'],true)||!$this->choiceValid($disposition,$recommendedModel,$models,$candidateAssessments)||array_keys($criterionRationale)!==array_keys($a['matrix']??[])||!$this->rationales($criterionRationale,$a['matrix']??[])
