        return$this->save($id,['schema'=>'imperium.oracle-model-recommendation/v1','recommendation_id'=>$id,'comparative_assessment'=>['id'=>$assessmentId,'digest'=>$a['record_digest'],'matrix_digest'=>$a['matrix_digest']],'case'=>$a['case'],'commission'=>$a['commission'],'catalogue_snapshot'=>$a['catalogue_snapshot'],'eligible_models'=>$models,'runtime_bindings'=>$a['runtime_bindings'],'actor'=>$actor,'disposition'=>$disposition,'recommended_model'=>$recommendedModel,'criterion_rationale'=>$criterionRationale,'candidate_assessments'=>$candidateAssessments,'issued_at'=>$issuedAt->format(DATE_ATOM),'recommendation_authority'=>['id'=>$authorityId,'consumed'=>true,'continuing_authority'=>false],'curia_selection_decision_authority'=>['authority_id'=>$decisionAuthorityId,'authority_single_use'=>true,'eligible_models'=>$models,'permitted_decisions'=>['SELECT_ELIGIBLE_MODEL','REJECT_ALL_MODELS','RETURN_NEW_COMMISSION'],'selection_decision_authority'=>true,'model_assignment_authority'=>false,'status'=>'OPEN_PENDING_CURIA_SELECTION_DECISION'],'ordinal_ranking'=>null,'selection_authority'=>false,'model_assignment_authority'=>false,'profile_mutation_authority'=>false,'provider_invocation_authority'=>false,'deployment_authority'=>false,'execution_authority'=>false,'status'=>'ORACLE_MODEL_RECOMMENDATION_SEALED_PENDING_CURIA_SELECTION_DECISION','sealed'=>true]);
