    private function choiceValid(string$d,?string$r,array$m,array$c):bool{if(array_keys($c)!==$m)return false;if('RECOMMEND_MODEL'===$d&&(!is_string($r)||!in_array($r,$m,true)))return false;if('RECOMMEND_MODEL'!==$d&&null!==$r)return false;foreach($c as$model=>$v){if(!is_array($v)||array_keys($v)!==['recommendation_role','rationale','advantages','disadvantages','limitations','contradictions']||!$this->text($v['rationale']??null)||!$this->strings($v['advantages']??null,true)||!$this->strings($v['disadvantages']??null,true)||!$this->strings($v['limitations']??null,true)||!$this->strings($v['contradictions']??null,true))return false;$role=$v['recommendation_role']??null;if('RECOMMEND_MODEL'===$d&&($model===$r?'RECOMMENDED':'ALTERNATIVE')!==$role)return false;if('NO_UNIQUE_RECOMMENDATION'===$d&&'COEQUAL'!==$role)return false;if('RECOMMEND_NONE'===$d&&'DECLINED'!==$role)return false;}return true;}
    private function rationales(array$r,array$m):bool{foreach($r as$criterion=>$v){$allowed=[];foreach($m[$criterion]??[]as$cell)$allowed=array_merge($allowed,$cell['source_ids']??[],$cell['claim_ids']??[]);$allowed=array_values(array_unique($allowed));if(!is_array($v)||array_keys($v)!==['rationale','evidence_refs']||!$this->text($v['rationale']??null)||!$this->strings($v['evidence_refs']??null)||[]!==array_diff($v['evidence_refs'],$allowed))return false;}return true;}
