    private function read(string$p,string$e):array{if(!is_file($p))throw new \RuntimeException($e);return json_decode((string)file_get_contents($p),true,512,JSON_THROW_ON_ERROR);}private function ok(array$r):bool{$d=$r['record_digest']??null;unset($r['record_digest']);return is_string($d)&&hash_equals($d,hash('sha256',CanonicalJson::encode($r)));}
    private function save(string$id,array$r):array{if(!is_dir($this->recommendations)&&!mkdir($this->recommendations,0770,true)&&!is_dir($this->recommendations))throw new \RuntimeException('OR64_MODEL_RECOMMENDATION_FAILED');$r['record_digest']=hash('sha256',CanonicalJson::encode($r));$p=$this->recommendations.'/'.$id.'.json';if(is_file($p))return$this->read($p,'OR64_MODEL_RECOMMENDATION_FAILED');file_put_contents($p,json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n",LOCK_EX);return$r;}
}
